INSERT INTO quest_template (entry, Method, ZoneOrSort, MinLevel, QuestLevel, Type, QuestFlags, PrevQuestId, ExclusiveGroup, Title, Details, Objectives, OfferRewardText, RequestItemsText, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, RewItemId1, RewItemCount1) VALUES (999200, 2, -344, 60, 60, 0, 0, 0, 0, 'Les Sept Fragments', 'Sept puissances ont été vaincues dans les raids de ce monde, et de chacune un éclat est resté entre vos mains.$B$BApportez-moi d\'abord les fragments du Sang d\'Hakkar, des Sables d\'Ossirian, du Cœur du Magma et d\'Onyxia. Je les fondrai en un cœur.', 'Rapporter les fragments du Sang d\'Hakkar, des Sables d\'Ossirian, du Cœur du Magma et d\'Onyxia.', 'Le cœur bat déjà. Il lui manque encore trois fragments.', 'Les fragments, $N ?', 999000, 999001, 999002, 999003, 1, 1, 1, 1, 999150, 1);
INSERT INTO quest_template (entry, Method, ZoneOrSort, MinLevel, QuestLevel, Type, QuestFlags, PrevQuestId, ExclusiveGroup, Title, Details, Objectives, OfferRewardText, RequestItemsText, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemId4, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3, RewChoiceItemCount4) VALUES (999201, 2, -344, 60, 60, 0, 0, 999200, 999201, 'La voie de l\'acier', 'Le cœur est prêt à devenir une arme. Celle-ci convient à un tank ou un combattant à deux mains.$B$BApportez-moi le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole. Choisissez bien : une seule arme légendaire par personne.', 'Rapporter le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole.', 'Les sept puissances ne font plus qu\'une. Elle est à vous.', 'Le cœur attend, $N.', 999150, 999004, 999005, 999006, 1, 1, 1, 1, 999130, 999102, 999103, 999104, 1, 1, 1, 1);
INSERT INTO quest_template (entry, Method, ZoneOrSort, MinLevel, QuestLevel, Type, QuestFlags, PrevQuestId, ExclusiveGroup, Title, Details, Objectives, OfferRewardText, RequestItemsText, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemId4, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3, RewChoiceItemCount4) VALUES (999202, 2, -344, 60, 60, 0, 0, 999200, 999201, 'La voie des lames jumelles', 'Le cœur est prêt à devenir une arme. Celle-ci convient à un combattant à deux armes.$B$BApportez-moi le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole. Choisissez bien : une seule arme légendaire par personne.', 'Rapporter le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole.', 'Les sept puissances ne font plus qu\'une. Elle est à vous.', 'Le cœur attend, $N.', 999150, 999004, 999005, 999006, 1, 1, 1, 1, 999131, 999132, 999133, 999134, 1, 1, 1, 1);
INSERT INTO quest_template (entry, Method, ZoneOrSort, MinLevel, QuestLevel, Type, QuestFlags, PrevQuestId, ExclusiveGroup, Title, Details, Objectives, OfferRewardText, RequestItemsText, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3) VALUES (999203, 2, -344, 60, 60, 0, 0, 999200, 999201, 'La voie du tireur', 'Le cœur est prêt à devenir une arme. Celle-ci convient à un tireur.$B$BApportez-moi le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole. Choisissez bien : une seule arme légendaire par personne.', 'Rapporter le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole.', 'Les sept puissances ne font plus qu\'une. Elle est à vous.', 'Le cœur attend, $N.', 999150, 999004, 999005, 999006, 1, 1, 1, 1, 999113, 999114, 999115, 1, 1, 1);
INSERT INTO quest_template (entry, Method, ZoneOrSort, MinLevel, QuestLevel, Type, QuestFlags, PrevQuestId, ExclusiveGroup, Title, Details, Objectives, OfferRewardText, RequestItemsText, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemId4, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3, RewChoiceItemCount4) VALUES (999204, 2, -344, 60, 60, 0, 0, 999200, 999201, 'La voie des arcanes et de la lumière', 'Le cœur est prêt à devenir une arme. Celle-ci convient à un lanceur de sorts ou un soigneur.$B$BApportez-moi le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole. Choisissez bien : une seule arme légendaire par personne.', 'Rapporter le Cœur des Sept et les fragments de l\'Aile noire, de l\'Œil de C\'Thun et de la Nécropole.', 'Les sept puissances ne font plus qu\'une. Elle est à vous.', 'Le cœur attend, $N.', 999150, 999004, 999005, 999006, 1, 1, 1, 1, 999116, 999135, 999119, 999136, 1, 1, 1, 1);
